import{_ as a,o,c as t,a7 as r}from"./chunks/framework.Du_9D64Q.js";const p=JSON.parse('{"title":"Crashes","description":"Troubleshooting crashes in Axolotl-PM.","frontmatter":{"title":"Crashes","outline":"deep","description":"Troubleshooting crashes in Axolotl-PM.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/issues/crashes"}]]},"headers":[],"relativePath":"docs/issues/crashes.md","filePath":"docs/issues/crashes.md","lastUpdated":1790689997000}'),s={name:"docs/issues/crashes.md"};function i(n,e,l,h,c,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="crashes" tabindex="-1">Crashes <a class="header-anchor" href="#crashes" aria-label="Permalink to &quot;Crashes&quot;">​</a></h1><p>Axolotl-PM may crash for a number of reasons:</p><ul><li>Bad / faulty plugins.</li><li>Running out of memory, due to too-low limit or a memory leak.</li><li>Bugs within the Axolotl-PM which are unrecoverable.</li></ul><p>In all of the above cases, a crashdump file will be generated in the <code>crashdumps</code> folder of your server.</p><h2 id="reporting-a-crash" tabindex="-1">Reporting a crash <a class="header-anchor" href="#reporting-a-crash" aria-label="Permalink to &quot;Reporting a crash&quot;">​</a></h2><p>Crash reports are automatically submitted to our <a href="https://crash.axolotl-pm.org" target="_blank" rel="noreferrer">Crash Archive</a> if your server is connected to the internet.</p><p>If successful, you will see a message like this in the server log: <code>[18:34:15] [Server thread/EMERGENCY]: The crash dump has been automatically submitted to the Crash Archive. You can view it on https://crash.axolotl-pm.org/view/5555 or use the ID #5555.</code></p><p>If you want to submit a crash report manually, you can do so at the <a href="https://crash.axolotl-pm.org/submit" target="_blank" rel="noreferrer">submit page</a>.</p><p>Crashdumps are searched and investigated regularly by the development team, so it is not necessary to submit an issue if your crashdump is in the <a href="https://crash.axolotl-pm.org" target="_blank" rel="noreferrer">Crash Archive</a>. Nonetheless, you can create one anyway at the <a href="https://github.com/axolotl-pm/PocketMine-MP/issues/new/choose" target="_blank" rel="noreferrer">issues page</a> if you want to give us extra information or draw our attention to the issue.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you want to opt-out of automatic crashdump submission, you can disable it using the <code>auto-report.enabled</code> setting in your <code>pocketmine.yml</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>When reporting a crash in Axolotl-PM, a crashdump file <strong>must</strong> be provided or we will not be able to help you.</p></div><h2 id="what-s-in-a-crashdump-file" tabindex="-1">What’s in a crashdump file? <a class="header-anchor" href="#what-s-in-a-crashdump-file" aria-label="Permalink to &quot;What&#39;s in a crashdump file?&quot;">​</a></h2><p>Crashdumps are <code>.log</code> files which contain important information which is used to identify, reproduce, and fix bugs. They contain human-readable information about the crash (the top part) and a machine-readable part which is used by our <a href="https://crash.axolotl-pm.org" target="_blank" rel="noreferrer">Crash Archive</a>.</p><p>A crashdump may contain the following information:</p><ul><li>Error message, file name, line number and error type</li><li>A stack trace of the error, which helps identify where the crash happened</li><li>A sample of code around the site of the crash, which helps to identify where the crash happened</li><li>Information about your operating system version and hardware (such as CPU model)</li><li>List of plugins installed on the server</li><li>Version of Axolotl-PM which you are using</li><li>The contents of your <code>pocketmine.yml</code> and <code>server.properties</code> file (sensitive information like passwords are redacted)</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can fine-tune what information is placed in crashdumps in your <code>pocketmine.yml</code> file under the <code>auto-report</code> section.</p></div>',16)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
